INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (138, 1, 'Git 은 무엇일까', 'Git 은 무엇을 하는 도구일까요?', '파일이 언제, 어떻게 바뀌었는지를 기억해요.', NULL, NULL, '[]', 'choice', '["파일을 자동으로 압축해 주는 도구", "서버를 만들어 주는 도구", "파일의 변경 이력을 저장하고, 원하는 시점으로 되돌릴 수 있게 해 주는 버전 관리 도구", "컴퓨터의 속도를 높여 주는 도구"]', 2, 'Git 은 내 컴퓨터에서 동작하는 도구이고, 원격 저장소 서비스는 그 이력을 인터넷에 올려 함께 쓰는 곳입니다. 둘은 다른 것이에요.', NULL, NULL, NULL, NULL),
  (138, 2, 'add 는 무엇을 할까', '`git add app.py` 는 무엇을 할까요?', '커밋할 후보 목록에 올려요.', NULL, NULL, '[]', 'choice', '["`app.py` 를 서버에 올린다", "`app.py` 의 변경을 스테이징 영역(다음 커밋에 넣을 목록)에 올린다", "`app.py` 를 삭제한다", "`app.py` 의 변경 이력을 기록한다"]', 1, 'add 는 "이 변경을 다음 커밋에 넣겠다"는 표시입니다. 실제 기록은 `commit` 때 만들어져요.', NULL, NULL, NULL, NULL),
  (138, 3, 'commit 은 무엇을 할까', '`git commit -m "메시지"` 는 무엇을 할까요?', '스냅샷 한 장을 찍는 것과 같아요.', NULL, NULL, '[]', 'choice', '["스테이징된 변경을 하나의 기록(커밋)으로 저장소에 남긴다", "스테이징된 변경을 원격 저장소에 올린다", "변경을 모두 취소한다", "브랜치를 새로 만든다"]', 0, '커밋은 내 컴퓨터의 저장소에만 쌓입니다. 다른 사람과 공유하려면 `push` 를 해야 해요.', NULL, NULL, NULL, NULL),
  (138, 4, 'status 읽기', '`git status` 에서 `Untracked files` 는 무슨 뜻일까요?', '"추적하지 않는 파일"이에요.', NULL, NULL, '[]', 'choice', '["삭제된 파일", "충돌이 난 파일", "이미 커밋된 파일", "Git 이 아직 관리하지 않는 새 파일"]', 3, '`git add` 를 하면 추적이 시작됩니다. 이미 추적 중인 파일을 고치면 `Changes not staged for commit`(modified)로 보여요.', NULL, NULL, NULL, NULL),
  (138, 5, 'diff 와 diff --staged', '`git diff` 와 `git diff --staged` 의 차이로 알맞은 것은 무엇일까요?', '아직 add 하지 않은 것과 add 한 것을 나눠서 봐요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`diff` 는 커밋된 변경을, `--staged` 는 삭제된 변경을 보여 준다", "`diff` 는 아직 add 하지 않은 변경, `--staged` 는 add 해서 다음 커밋에 들어갈 변경을 보여 준다", "`--staged` 는 원격 저장소와 비교한다"]', 2, '커밋하기 전에 `diff --staged` 로 "무엇이 들어가는지" 마지막으로 확인하는 습관이 좋습니다.', NULL, NULL, NULL, NULL),
  (138, 6, '커밋 메시지는 왜 쓸까', '좋은 커밋 메시지의 가장 큰 목적은 무엇일까요?', '나중에 이력을 읽는 사람을 생각해 보세요.', NULL, NULL, '[]', 'choice', '["Git 이 커밋을 저장하려면 꼭 필요한 형식이라서", "나중에 이력을 볼 때 무엇을 왜 바꿨는지 알 수 있게 하려고", "커밋을 더 빠르게 만들려고", "파일 크기를 줄이려고"]', 1, '"수정" 같은 메시지는 나중에 쓸모가 없습니다. "로그인 실패 시 오류 메시지 추가"처럼 변경의 내용과 이유가 보이게 쓰세요.', NULL, NULL, NULL, NULL),
  (138, 7, '브랜치는 무엇일까', 'Git 의 브랜치(branch)는 무엇일까요?', '기본 줄기에서 갈라져 나온 작업 줄기예요.', NULL, NULL, '[]', 'choice', '["기존 작업에 영향을 주지 않고 따로 작업할 수 있는 갈래 (가볍게 만들고 지울 수 있다)", "저장소 전체의 복사본", "삭제된 파일을 모아 두는 휴지통", "원격 저장소의 다른 이름"]', 0, '새 기능은 브랜치에서 만들고 완성되면 합칩니다. Git 의 브랜치는 가벼워서 자주 만들고 지워도 괜찮아요.', NULL, NULL, NULL, NULL),
  (138, 8, 'HEAD 는 무엇일까', 'Git 에서 `HEAD` 는 무엇을 가리킬까요?', '"지금 내가 있는 곳"을 가리키는 표지예요.', NULL, NULL, '[]', 'choice', '["원격 저장소의 주소", "가장 처음 만든 커밋", "삭제 예정인 커밋", "지금 작업 중인 브랜치(의 가장 최근 커밋)"]', 3, '`HEAD~1` 은 현재 커밋의 한 단계 앞(부모) 커밋입니다. 되돌릴 때 위치를 가리키는 데 자주 써요.', NULL, NULL, NULL, NULL),
  (138, 9, '충돌 표시 읽기', '파일 안에 `<<<<<<< HEAD`, `=======`, `>>>>>>> feature` 가 보입니다. 무엇일까요?', '두 쪽의 내용이 같은 줄을 서로 다르게 고쳤어요.', NULL, NULL, '[]', 'choice', '["파일이 손상됐다는 표시이다", "Git 이 자동으로 합친 결과이다", "병합 충돌 표시이다. 두 내용 중 무엇을 남길지 직접 고르고 표시 줄을 지워야 한다", "주석이라서 지워도 되고 두어도 된다"]', 2, '`=======` 위쪽이 내 쪽(HEAD), 아래쪽이 합치려는 쪽입니다. 고친 뒤 표시 줄을 모두 지우고 `add` 와 `commit` 으로 마무리하세요.', NULL, NULL, NULL, NULL),
  (138, 10, 'fetch 와 pull 의 차이', '`git fetch` 와 `git pull` 의 차이로 알맞은 것은 무엇일까요?', 'pull 은 가져오기에 한 가지가 더 붙어요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`fetch` 는 원격의 새 내용을 가져오기만 하고, `pull` 은 가져온 뒤 내 브랜치에 합치기까지 한다", "`fetch` 가 합치기까지 하고 `pull` 은 가져오기만 한다", "`pull` 은 내 변경을 원격에 올린다"]', 1, '`pull` 은 `fetch` 와 `merge` 를 합친 것입니다. 무슨 변경이 있는지 먼저 보고 싶다면 `fetch` 부터 쓰세요.', NULL, NULL, NULL, NULL),
  (138, 11, 'push 가 거절될 때', '`git push` 를 했더니 `rejected` 와 "원격에 내 로컬에 없는 커밋이 있다"는 안내가 나왔습니다. 먼저 할 일은 무엇일까요?', '내가 모르는 변경이 원격에 있어요.', NULL, NULL, '[]', 'choice', '["`git pull` 로 원격의 새 커밋을 받아 합친 뒤 다시 push 한다", "`git push --force` 로 덮어쓴다", "저장소를 지우고 새로 만든다", "아무 일도 하지 않고 기다린다"]', 0, '강제로 올리면 다른 사람의 커밋이 사라질 수 있어 위험합니다. 먼저 받아서 합친 뒤 올리는 것이 기본이에요.', NULL, NULL, NULL, NULL),
  (138, 12, 'reset --hard 의 위험', '`git reset --hard` 를 실행하면 어떤 위험이 있을까요?', 'hard 는 작업 폴더까지 되돌려요.', NULL, NULL, '[]', 'choice', '["원격 저장소가 삭제된다", "모든 브랜치가 삭제된다", "아무 위험이 없다", "아직 커밋하지 않은 변경이 작업 폴더에서도 사라져 되돌릴 수 없다"]', 3, '실행하기 전에 `git status` 로 지울 변경이 없는지 확인하세요. 아직 확신이 없다면 `git stash` 로 임시 보관하는 방법이 있어요.', NULL, NULL, NULL, NULL),
  (138, 13, 'revert 와 reset', '이미 push 한 커밋을 취소해야 합니다. 이력을 지우지 않고 "취소하는 새 커밋"을 만드는 명령은 무엇일까요?', '다른 사람이 이미 그 이력을 받았을 수 있어요.', NULL, NULL, '[]', 'choice', '["`git reset --hard 커밋`", "`git clean -fd`", "`git revert 커밋`", "`git init`"]', 2, '공유한 이력을 `reset` 으로 바꾸면 다른 사람과 어긋납니다. 이미 공유한 변경은 `revert` 로 안전하게 되돌리세요.', NULL, NULL, NULL, NULL),
  (138, 14, '.gitignore 의 역할', '`.gitignore` 파일에 `*.log` 를 적으면 어떤 일이 일어날까요?', '추적하지 않을 파일의 패턴 목록이에요.', NULL, NULL, '[]', 'choice', '["`.log` 파일이 삭제된다", "`.log` 로 끝나는 새 파일은 Git 이 추적하지 않는다 (이미 추적 중인 파일은 영향이 없다)", "`.log` 파일이 암호화된다", "이미 커밋된 `.log` 파일도 저장소에서 자동으로 빠진다"]', 1, '비밀번호가 든 설정 파일, 빌드 결과물, 로그를 올리지 않게 막습니다. 이미 올린 파일은 `git rm --cached` 로 추적을 끊어야 해요.', NULL, NULL, NULL, NULL),
  (138, 15, '저장소 만들기', '현재 폴더를 **새 Git 저장소로** 만드는 명령입니다. 빈칸을 채우세요.', '"초기화"라는 뜻의 영어 단어 줄임이에요.', NULL, NULL, '[]', 'fill', '["init", "new", "create", "start"]', NULL, '`git init` 은 `.git` 폴더를 만들어 이 폴더를 저장소로 바꿉니다. 이미 저장소인 폴더에서 다시 실행하지 않아도 돼요.', '[0]', 'git {0}', NULL, NULL),
  (138, 16, '모든 변경 올리기', '현재 폴더의 **모든 변경을 스테이징 영역에** 올리는 명령입니다. 빈칸을 채우세요.', '현재 폴더를 뜻하는 점이에요.', NULL, NULL, '[]', 'fill', '[".", "-all", "..", "--none"]', NULL, '`git add .` 은 현재 폴더 아래의 변경을 모두 올립니다. 비밀 파일이 섞이지 않았는지 `status` 로 먼저 확인하세요.', '[0]', 'git add {0}', NULL, NULL),
  (138, 17, '메시지와 함께 커밋', '메시지를 바로 적어 **커밋하는** 옵션입니다. 빈칸을 채우세요.', 'message 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-m", "-a", "-c", "-p"]', NULL, '`-m` 이 없으면 편집기가 열려 메시지를 쓰게 됩니다. 급하면 `-m` 으로 한 줄만 적어요.', '[0]', 'git commit {0} "첫 커밋"', NULL, NULL),
  (138, 18, '이력 한 줄씩 보기', '커밋 이력을 **한 줄씩 짧게** 보는 명령입니다. 빈칸을 채우세요.', '"기록"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["log", "history", "list", "show-all"]', NULL, '`git log` 는 이력을 보여 주고, `--oneline` 은 커밋 하나를 한 줄로 줄입니다. 그래프로 보려면 `--graph` 를 더해요.', '[0]', 'git {0} --oneline', NULL, NULL),
  (138, 19, '커밋될 내용 확인', '`add` 한 변경, 즉 **다음 커밋에 들어갈 내용**을 보는 옵션입니다. 빈칸을 채우세요.', '스테이징된(staged) 이라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--staged", "--all", "--saved", "--commit"]', NULL, '커밋 직전에 한 번 보면 실수로 넣은 파일을 잡아낼 수 있습니다. `--cached` 도 같은 뜻이에요.', '[0]', 'git diff {0}', NULL, NULL),
  (138, 20, '브랜치 옮겨 가기', '`feature` 브랜치로 **이동하는** 명령입니다. 빈칸을 채우세요.', '"전환하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["switch", "merge", "fetch", "push"]', NULL, '`git switch` 는 브랜치를 옮기는 명령입니다. 새로 만들면서 옮기려면 `git switch -c 이름` 이에요.', '[0]', 'git {0} feature', NULL, NULL),
  (138, 21, '브랜치 합치기', '지금 브랜치에 `feature` 브랜치의 변경을 **합치는** 명령입니다. 빈칸을 채우세요.', '"합병"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["merge", "combine", "join", "add"]', NULL, '합칠 때는 받는 쪽 브랜치(예: main)로 먼저 이동한 뒤 실행합니다. 같은 줄을 고쳤다면 충돌이 날 수 있어요.', '[0]', 'git {0} feature', NULL, NULL),
  (138, 22, '원격에 올리기', '내 커밋을 `origin` 의 `main` 브랜치에 **올리는** 명령입니다. 빈칸을 채우세요.', '"밀어 넣다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["push", "send", "upload", "commit"]', NULL, '`push` 는 내 저장소의 커밋을 원격에 보냅니다. 거절되면 먼저 `pull` 로 받아 합치세요.', '[0]', 'git {0} origin main', NULL, NULL),
  (138, 23, '원격에서 받아 합치기', '원격의 새 커밋을 **가져와 합치는** 명령입니다. 빈칸을 채우세요.', '"끌어당기다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["pull", "sync", "get", "download"]', NULL, '`pull` 은 가져오기와 합치기를 한 번에 합니다. 작업 중인 변경이 있으면 먼저 커밋하거나 stash 하세요.', '[0]', 'git {0}', NULL, NULL),
  (138, 24, '스테이징 취소하기', '`add` 한 `app.py` 를 **스테이징에서 빼는** 옵션입니다. 빈칸을 채우세요.', '"스테이징된"이라는 뜻의 단어가 들어가요.', NULL, NULL, '[]', 'fill', '["--staged", "--undo", "--hard", "--all"]', NULL, '`--staged` 는 파일 내용은 그대로 두고 스테이징만 취소합니다. 파일 내용까지 되돌리는 것과는 달라요.', '[0]', 'git restore {0} app.py', NULL, NULL),
  (138, 25, '보관한 변경 꺼내기', '`git stash` 로 임시 보관한 변경을 **꺼내서 다시 적용하는** 명령입니다. 빈칸을 채우세요.', '"튀어나오다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["pop", "take", "back", "undo"]', NULL, '`stash` 는 하던 작업을 잠깐 치워 둘 때 씁니다. `pop` 은 꺼내서 적용하고 보관함에서는 지워요.', '[0]', 'git stash {0}', NULL, NULL),
  (138, 26, '처음 저장소 만들고 첫 커밋', '새 폴더를 저장소로 만들어 첫 커밋을 남기는 순서입니다. 순서에 맞게 놓아 보세요.', '저장소 → 파일 → 스테이징 → 커밋 순서예요.', NULL, NULL, '[]', 'order', '["`git init` 으로 저장소를 만든다", "`README.md` 파일을 만든다", "`git add .` 으로 변경을 스테이징한다", "`git commit -m \\"첫 커밋\\"` 으로 기록한다"]', NULL, '커밋 전에 `git status` 로 무엇이 들어가는지 확인하는 습관이 좋습니다. 첫 커밋 뒤 `git log` 로 기록을 확인해 보세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (138, 27, '브랜치에서 작업하고 합치기', '기능 브랜치에서 작업하고 main 에 합치는 순서입니다. 순서에 맞게 놓아 보세요.', '브랜치 만들기 → 커밋 → main 으로 이동 → 합치기 순서예요.', NULL, NULL, '[]', 'order', '["`git switch -c feature` 로 브랜치를 만들고 이동한다", "파일을 고치고 `git add`, `git commit` 으로 기록한다", "`git switch main` 으로 main 으로 돌아온다", "`git merge feature` 로 변경을 합친다"]', NULL, '합치는 쪽(main)으로 먼저 이동해야 합니다. 합친 뒤 필요 없는 브랜치는 `git branch -d feature` 로 지워요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (138, 28, '협업의 기본 흐름', '원격 저장소를 함께 쓰는 하루 작업의 기본 순서입니다. 순서에 맞게 놓아 보세요.', '받기 → 작업 → 기록 → 올리기 순서예요.', NULL, NULL, '[]', 'order', '["`git pull` 로 최신 내용을 받는다", "파일을 고친다", "`git add` 와 `git commit` 으로 기록한다", "`git push` 로 원격에 올린다"]', NULL, '작업 전에 먼저 받아 두면 push 가 거절되거나 충돌이 날 가능성이 줄어듭니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (138, 29, '병합 충돌 해결하기', '병합 중 충돌이 났을 때의 해결 순서입니다. 순서에 맞게 놓아 보세요.', '충돌 확인 → 고치기 → 스테이징 → 마무리 순서예요.', NULL, NULL, '[]', 'order', '["`git status` 로 충돌이 난 파일을 확인한다", "파일을 열어 `<<<<<<<`, `=======`, `>>>>>>>` 표시를 보며 남길 내용을 정하고 표시 줄을 지운다", "`git add 파일` 로 해결했다고 표시한다", "`git commit` 으로 병합을 마무리한다"]', NULL, '표시 줄을 하나라도 남기면 코드가 깨집니다. 마무리 전에 파일을 한 번 더 훑어 확인하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
